(7210754, 1111326, 60173, '<td valign="top">At a quick glance of the thumbnail, I thought this was a spider in its web. Admittedly, I don''t look at many parachuting photos, but I''ve never noticed the intricacy of the cables before.</td>', 'At a quick glance of the thumbnail, I thought this was a spider in its web. Admittedly, I don''t look at many parachuting photos, but I''ve never noticed the intricacy of the cables before.', '2014-05-01 12:57:23.000000', NULL, 1),
(7210755, 1110821, 60173, '<td valign="top">Now, there''s a story to be told... Nice tones.</td>', 'Now, there''s a story to be told... Nice tones.', '2014-05-01 13:02:49.000000', NULL, 1),
