(7213956, 1107948, 67258, '<td valign="top">As a wildlife photograph, I would generally prefer the subject tack sharp, but this isn''t a straight wildlife photo; rather, it is the essence of Spring.  I like it.</td>', 'As a wildlife photograph, I would generally prefer the subject tack sharp, but this isn''t a straight wildlife photo; rather, it is the essence of Spring.  I like it.', '2014-05-07 15:12:53.000000', NULL, 1),
(7213957, 1111065, 67258, '<td valign="top">Love it!</td>', 'Love it!', '2014-05-07 15:15:06.000000', NULL, 1),
(7213958, 1110920, 67258, '<td valign="top">Beautiful light - turns an ordinary duck into something far less ordinary.</td>', 'Beautiful light - turns an ordinary duck into something far less ordinary.', '2014-05-07 15:23:07.000000', NULL, 1),
(7213959, 1111362, 67258, '<td valign="top">Cracking - that is some attitude!</td>', 'Cracking - that is some attitude!', '2014-05-07 15:23:36.000000', NULL, 1),
(7213961, 1111110, 67258, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2014-05-07 15:24:53.000000', NULL, 1),
(7213964, 1110810, 67258, '<td valign="top">You have captured a great sense of character and personality here.  A portrait with a strong narrative, too.</td>', 'You have captured a great sense of character and personality here.  A portrait with a strong narrative, too.', '2014-05-07 15:27:21.000000', NULL, 1),
(7213966, 1111364, 67258, '<td valign="top">Definitely strange!</td>', 'Definitely strange!', '2014-05-07 15:27:48.000000', NULL, 1),
(7213968, 1111336, 67258, '<td valign="top">Aww!  Seriously, delightfully adorable.  That little hand creeping up is so delicate.</td>', 'Aww!  Seriously, delightfully adorable.  That little hand creeping up is so delicate.', '2014-05-07 15:30:47.000000', NULL, 1),
(7213970, 1110821, 67258, '<td valign="top">Wonderful!</td>', 'Wonderful!', '2014-05-07 15:32:09.000000', NULL, 1),
(7213973, 1110889, 108580, '<td valign="top">My top pick. 10. I love morning light and I particularly like minimalism in silhouettes and horisons. 800px and 72dpi (banding around the sun) does not do this justice.</td>', 'My top pick. 10. I love morning light and I particularly like minimalism in silhouettes and horisons. 800px and 72dpi (banding around the sun) does not do this justice.', '2014-05-07 15:56:30.000000', NULL, 1),
(7213974, 1108250, 108580, '<td valign="top">Beautiful scape. Intoxicating amount of vanishing point and leading lines. 800px and 72dpi does not do this justice. 9.</td>', 'Beautiful scape. Intoxicating amount of vanishing point and leading lines. 800px and 72dpi does not do this justice. 9.', '2014-05-07 15:57:27.000000', NULL, 1),
(7213975, 1110767, 108580, '<td valign="top">9. Wonderful B&amp;W PP. I''d hazard a guess this is a GregoryB? :)<br/>I''ve walked over that bridge and around those sails a few times...<br/>Stunner. 800px and 72dpi is a waste for an image like this.</td>', '9. Wonderful B&W PP. I''d hazard a guess this is a GregoryB? :)I''ve walked over that bridge and around those sails a few times...Stunner. 800px and 72dpi is a waste for an image like this.', '2014-05-07 15:58:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7213976, 1111217, 108580, '<td valign="top">I''m a sucker for birds and minimalism. Wonderful high key. 9 and a fave.</td>', 'I''m a sucker for birds and minimalism. Wonderful high key. 9 and a fave.', '2014-05-07 15:59:33.000000', NULL, 1),
(7213977, 1109295, 108580, '<td valign="top">M.C. Escher..............in a photo! 8 and a fave.</td>', 'M.C. Escher..............in a photo! 8 and a fave.', '2014-05-07 16:00:37.000000', NULL, 1),
(7213979, 1111353, 108580, '<td valign="top">If you look closely, there they are! I''d be surprised if many voters actually took the time. 8</td>', 'If you look closely, there they are! I''d be surprised if many voters actually took the time. 8', '2014-05-07 16:01:46.000000', NULL, 1),
(7213980, 1110876, 108580, '<td valign="top">Wonderful study. Perfect portrayal of life sapping ageing. 8. Paul?</td>', 'Wonderful study. Perfect portrayal of life sapping ageing. 8. Paul?', '2014-05-07 16:02:42.000000', NULL, 1),
(7213982, 1110591, 108580, '<td valign="top">Lovely conversion and Biblical light. 8</td>', 'Lovely conversion and Biblical light. 8', '2014-05-07 16:03:03.000000', NULL, 1),
(7213983, 1111316, 108580, '<td valign="top">You lucky sod. 8.</td>', 'You lucky sod. 8.', '2014-05-07 16:03:38.000000', NULL, 1),
(7213984, 1110073, 108580, '<td valign="top">Fabulous sunrise. Super lines. Magical near duotone. 8</td>', 'Fabulous sunrise. Super lines. Magical near duotone. 8', '2014-05-07 16:04:15.000000', NULL, 1),
(7213985, 1107946, 108580, '<td valign="top">Beautiful separation and smooth BG. Perfect for Audubon. Perfect shallow DOF on the eye.</td>', 'Beautiful separation and smooth BG. Perfect for Audubon. Perfect shallow DOF on the eye.', '2014-05-07 16:05:33.000000', NULL, 1),
(7213987, 1111349, 108580, '<td valign="top">Fabulous study. Not as crisp as many may want or expect but doesn''t always need to be. Other factors make up for that such as perfect Focal Length to get the wings and extremities in. Good look toward camera, flight toward camera and slightly open bill. 7.</td>', 'Fabulous study. Not as crisp as many may want or expect but doesn''t always need to be. Other factors make up for that such as perfect Focal Length to get the wings and extremities in. Good look toward camera, flight toward camera and slightly open bill. 7.', '2014-05-07 16:08:23.000000', NULL, 1),
(7213989, 1109834, 108580, '<td valign="top">I''d like to see more motor-sport on DPC (I shoot a lot of bikes and cars). This is a super shot in trying conditions. I''d just crop out the slightly distracting top right red area. More please. 7</td>', 'I''d like to see more motor-sport on DPC (I shoot a lot of bikes and cars). This is a super shot in trying conditions. I''d just crop out the slightly distracting top right red area. More please. 7', '2014-05-07 16:10:06.000000', NULL, 1),
(7214019, 1110930, 152252, '<td valign="top">Amazing capture!</td>', 'Amazing capture!', '2014-05-07 17:58:54.000000', NULL, 1),
(7214020, 1111461, 152252, '<td valign="top">A very intense portrait full of suspense. Their expressions are amazing. I also love how it''s framed. I can see it ending up in a history of photography book in the future. My only 10 so far (voted earlier).<br/> <br/>And this is for you:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1108908" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/150000-154999/152252/120/Copyrighted_Image_Reuse_Prohibited_1108908.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/150000-154999/152252/120/Copyrighted_Image_Reuse_Prohibited_1108908.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/150000-154999/152252/120/Copyrighted_Image_Reuse_Prohibited_1108908.jpg"/></a></td>', 'A very intense portrait full of suspense. Their expressions are amazing. I also love how it''s framed. I can see it ending up in a history of photography book in the future. My only 10 so far (voted earlier). And this is for you:', '2014-05-07 18:00:19.000000', NULL, 1),
